import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { BdfDocument, BufferSource, decode, MAX_PAGE_SIZE } from '@bdfkit/core';
import { convert_fixture, convert_summary, convert_animated, convert_warnings, accepts } from '../../_build/js/debug/build/compat/image/image.js';

// Generated by shibukawa/bdf at 4f9af52 using its converter/image testdata.
const fixtures = JSON.parse(await readFile(new URL('./upstream.json', import.meta.url)));
for (const expected of fixtures) {
  const input = Buffer.from(expected.input, 'base64');
  assert.equal(convert_summary(input, expected.name, expected.title), expected.summary);
  assert.equal(convert_animated(input), expected.animated);
  assert.deepEqual(convert_warnings(input), expected.warnings);
  for (const [n, accepted] of Object.entries(expected.prefixes)) {
    const actual = accepts(input.subarray(0, Number(n)));
    // Some XML syntax errors are still rejected even when upstream recovers.
    if (expected.format === 'svg' && accepted && !actual && Number(n) < input.length) continue;
    assert.equal(actual, accepted, `${expected.name}: prefix ${n}`);
  }
  const source = new BufferSource(convert_fixture(input, expected.name, expected.title));
  const manifest = await source.manifest();
  if (expected.pageW > MAX_PAGE_SIZE || expected.pageH > MAX_PAGE_SIZE) {
    // Upstream emits the oversized page, but its BDF reader refuses to open it.
    await assert.rejects(BdfDocument.open(source), /page (width|height).*out of range/);
  } else {
    await BdfDocument.open(source);
  }
  assert.equal(manifest.meta.source, expected.format);
  assert.equal(manifest.meta.generator, 'bdf-go/0.1');
  assert.deepEqual(manifest.meta.dc ?? {}, expected.dc);
  assert.equal(manifest.views[0].pages[0].w, expected.pageW);
  assert.equal(manifest.views[0].pages[0].h, expected.pageH);
  assert.equal(manifest.parts[0].h, expected.imageHash);
  const part = async hash => {
    const entry = manifest.parts.find(value => value.h === hash);
    assert.ok(entry);
    return decode(await source.stored(entry), entry.enc, entry.size ?? 0);
  };
  assert.deepEqual(Buffer.from(await part(expected.imageHash)), input);
  const object = manifest.views[0].pages[0].layers[0].obj;
  assert.deepEqual(Buffer.from(await part(object)), Buffer.from(expected.object, 'base64'));
}
console.log('Image conversion compatibility: BMP, ICO, JPEG, PNG, GIF, WebP, AVIF and SVG match upstream pages, original bytes and BOBJ. Some malformed SVG acceptance remains unsupported.');
